ValidationRule.errorConditionFormula:
IF( $Permission.Skip_Validations_Permission, false, 
AND(Refused_to_provide_SOW__c = TRUE,
OR(NOT(ISBLANK(Source_of_Wealth_for_Individuals__c)),
NOT(ISBLANK(Source_of_Wealth__c))
),
OR(
ISCHANGED(Source_of_Wealth_for_Individuals__c),
ISCHANGED(Source_of_Wealth__c),
$Permission.Skip_Validations_Permission = FALSE
)
)
)
